import{_ as i,o as a,c as t,ae as o}from"./chunks/framework.B2ul6ABY.js";const u=JSON.parse('{"title":"Incidents","description":"","frontmatter":{},"headers":[],"relativePath":"runbook/incidents.md","filePath":"runbook/incidents.md"}'),n={name:"runbook/incidents.md"};function s(r,e,l,d,c,h){return a(),t("div",null,[...e[0]||(e[0]=[o(`<h1 id="incidents" tabindex="-1">Incidents <a class="header-anchor" href="#incidents" aria-label="Permalink to &quot;Incidents&quot;">​</a></h1><p>Use this page when runtime, UI, auth, evidence, or agent behavior is degraded. Start with <a href="./operations.html">Operations</a> for normal procedures.</p><h2 id="first-response-checklist" tabindex="-1">First response checklist <a class="header-anchor" href="#first-response-checklist" aria-label="Permalink to &quot;First response checklist&quot;">​</a></h2><ol><li>Check public health:</li></ol><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> http://localhost:8080/health</span></span></code></pre></div><ol start="2"><li>Check authenticated state:</li></ol><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -H</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;Authorization: Bearer </span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$SAIVAGE_API_TOKEN</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">  http://localhost:8080/api/state</span></span></code></pre></div><ol start="3"><li>Open Debug and inspect errors, timeline, doctor, supervision, processes, notifications, MCP, and control actions.</li><li>Open affected card detail or agent conversation for evidence and history.</li><li>Pause or freeze before manual intervention if state is still mutating.</li></ol><h2 id="unauthorized-api-or-websocket-access" tabindex="-1">Unauthorized API or WebSocket access <a class="header-anchor" href="#unauthorized-api-or-websocket-access" aria-label="Permalink to &quot;Unauthorized API or WebSocket access&quot;">​</a></h2><p>Symptoms:</p><ul><li><code>401 Unauthorized</code> from <code>/api/*</code>.</li><li>WebSocket does not connect.</li><li>UI shows unauthorized/no-token state.</li><li>Card detail shows <code>Unauthorized</code>.</li></ul><p>What to do:</p><ol><li>Confirm <code>SAIVAGE_API_TOKEN</code> is configured on the server.</li><li>Confirm the client sends <code>Authorization: Bearer &lt;token&gt;</code> or <code>?token=&lt;token&gt;</code>.</li><li>Confirm <code>/health</code> works without auth.</li><li>Confirm <code>/docs/</code> remains public.</li><li>Re-enter the token in the Web Control Room token modal when needed.</li></ol><h2 id="stale-reconnecting-or-offline-ui" tabindex="-1">Stale, reconnecting, or offline UI <a class="header-anchor" href="#stale-reconnecting-or-offline-ui" aria-label="Permalink to &quot;Stale, reconnecting, or offline UI&quot;">​</a></h2><p>A stale banner means a relevant notification arrived after the last successful fetch. Reconnecting/offline states mean WebSocket freshness is degraded; REST reloads remain authoritative.</p><p>What to do:</p><ol><li>Refresh the relevant view.</li><li>Use <code>/api/state</code>, card detail, and Debug as the source of truth after reconnect.</li><li>If offline persists, verify the service process, port binding, and journal logs.</li></ol><h2 id="preview-only-or-denied-control-action" tabindex="-1">Preview-only or denied control action <a class="header-anchor" href="#preview-only-or-denied-control-action" aria-label="Permalink to &quot;Preview-only or denied control action&quot;">​</a></h2><p>Mutating controls use a static authorization table keyed by actor, surface, and safety class.</p><ul><li><code>deny</code> fails and writes a denied audit entry.</li><li><code>preview_only</code> returns a preview and <code>preview_hash</code>; commit requires <code>confirmed: true</code> and the matching hash.</li><li><code>allow</code> commits immediately through the canonical service.</li></ul><p>What to do:</p><ol><li>Confirm the intended surface: <code>web-chat</code>, <code>web-ui</code>, <code>rest</code>, <code>cli</code>, <code>runtime</code>, or <code>telegram</code>.</li><li>Re-submit with <code>confirmed: true</code> and the matching preview hash when appropriate.</li><li>Inspect <code>/api/control-actions</code> to see whether the request was denied, rejected, previewed, or committed.</li><li>Change the authz table in <code>src/agents/authz.ts</code> rather than bypassing individual routes if policy is wrong.</li></ol><h2 id="frozen-paused-or-error-runtime-state" tabindex="-1">Frozen, paused, or error runtime state <a class="header-anchor" href="#frozen-paused-or-error-runtime-state" aria-label="Permalink to &quot;Frozen, paused, or error runtime state&quot;">​</a></h2><p>Generic resume is intentionally rejected for <code>frozen</code> and <code>error</code> states. This is a safety rule.</p><p>What to do:</p><ol><li>If paused, use <code>POST /api/runtime/resume</code>.</li><li>If frozen, use <code>POST /api/runtime/resume-from-freeze</code>.</li><li>If error, inspect Debug errors/timeline and fix the underlying failure before attempting recovery.</li><li>Freeze before disruptive filesystem or deployment intervention.</li></ol><h2 id="running-agent-ignored-a-change-or-cannot-finish" tabindex="-1">Running agent ignored a change or cannot finish <a class="header-anchor" href="#running-agent-ignored-a-change-or-cannot-finish" aria-label="Permalink to &quot;Running agent ignored a change or cannot finish&quot;">​</a></h2><p>Likely causes:</p><ul><li>Operator changed a card while an agent was running.</li><li>A directive or escalation note arrived.</li><li>A blocking notification was not acknowledged.</li><li>Executor/reviewer dispatch was held for notification delivery.</li></ul><p>What to do:</p><ol><li>Inspect card history and notes.</li><li>Inspect the session conversation for synthetic operator-update messages.</li><li>Ensure the agent used <code>diff_card</code>, <code>get_card_history_entry</code>, <code>get_note</code>, or similar read tools as needed.</li><li>Ensure blocking notifications are acknowledged before accepting terminal results.</li><li>Treat repeated failure after reinvocation as an agent/tooling issue rather than forcing completion.</li></ol><h2 id="generated-file-preview-is-blocked-or-redacted" tabindex="-1">Generated file preview is blocked or redacted <a class="header-anchor" href="#generated-file-preview-is-blocked-or-redacted" aria-label="Permalink to &quot;Generated file preview is blocked or redacted&quot;">​</a></h2><p>Expected causes include secret-path policy, containment violation, oversize content, binary files, or symlinks resolving outside the project root.</p><p>Examples:</p><ul><li><code>.saivage/auth-profiles.json</code> is blocked.</li><li><code>.saivage/saivage.json</code> is redacted-only.</li></ul><p>What to do:</p><ul><li>Treat blocked/redacted states as intentional safety behavior first.</li><li>Use card detail and Files view blocked reasons before raw filesystem reads.</li><li>Do not bypass API preview policy during routine operation.</li></ul><h2 id="card-detail-evidence-or-review-is-incomplete" tabindex="-1">Card detail evidence or review is incomplete <a class="header-anchor" href="#card-detail-evidence-or-review-is-incomplete" aria-label="Permalink to &quot;Card detail evidence or review is incomplete&quot;">​</a></h2><p>Different states mean different things:</p><ul><li><code>No operator-facing evidence is recorded yet</code> — active/running work has not produced evidence yet.</li><li>Incomplete evidence on a blocked/done/failed card — completion is not operator-verified.</li><li>Missing files — evidence references were recorded, but the file is gone.</li><li><code>Review failed</code> or <code>Not reviewed</code> — card completion is not accepted by reviewer evidence alone.</li></ul><p>What to do:</p><ol><li>Check verification commands, review result, dispatch summary, and evidence cards.</li><li>Inspect cited evidence-card IDs.</li><li>Inspect card history for acceptance changes after evidence was produced.</li><li>Do not accept completion based on status alone.</li></ol><h2 id="agent-tool-invocation-failures" tabindex="-1">Agent/tool invocation failures <a class="header-anchor" href="#agent-tool-invocation-failures" aria-label="Permalink to &quot;Agent/tool invocation failures&quot;">​</a></h2><p>Use Debug before manual repair:</p><ul><li><code>GET /api/debug/errors</code></li><li><code>GET /api/debug/timeline</code></li><li><code>GET /api/debug/doctor</code></li><li><code>GET /api/debug/supervision</code></li><li><code>GET /api/processes</code></li></ul><p>Correlate failed sessions in Agents with runtime events and process views. Provider errors should be redacted before persistence and notification.</p><h2 id="validation-command-confusion" tabindex="-1">Validation-command confusion <a class="header-anchor" href="#validation-command-confusion" aria-label="Permalink to &quot;Validation-command confusion&quot;">​</a></h2><p>Root <code>npm test</code> runs backend Jest under <code>tests/</code>. Web UI suites run under Vitest from <code>web/</code> or via root wrappers.</p><p>Preferred analyst UI validation wrapper:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> web:test:analyst-ui</span></span></code></pre></div><p>Core validation commands:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> typecheck</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> docs:verify</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> test</span></span></code></pre></div>`,52)])])}const f=i(n,[["render",s]]);export{u as __pageData,f as default};
